body.script:
(function () {

    const html = document.documentElement;

    function updateTheme() {

        const isDark = html.classList.contains("dark-mode");

        // Update Toggle Icons
        document.querySelectorAll(".themeIcon").forEach(function (icon) {
            icon.src = isDark ? "images/sun.svg" : "images/moon.svg";
        });

        // Update Theme Images
        document.querySelectorAll(".theme-image").forEach(function (img) {

            const newSrc = isDark ? img.dataset.dark : img.dataset.light;

            if (newSrc) {
                img.setAttribute("src", newSrc);
            }

        });

    }

    function applyTheme(theme) {

        if (theme === "dark") {html.classList.add("dark-mode");} else {html.classList.remove("dark-mode");}

        localStorage.setItem("theme", theme);

        // Run multiple times to catch late-loaded images/includes
        updateTheme();

        requestAnimationFrame(updateTheme);

        setTimeout(updateTheme, 100);

        setTimeout(updateTheme, 300);

    }

    const savedTheme = localStorage.getItem("theme") || "light";

    // First Run
    applyTheme(savedTheme);

    // DOM Ready
    document.addEventListener("DOMContentLoaded", function () {applyTheme(savedTheme);});

    // All Images Loaded
    window.addEventListener("load", function () {applyTheme(savedTheme);});

    // Desktop + Mobile Buttons
    document.addEventListener("click", function (e) {

        const toggle = e.target.closest(".themeToggle");

        if (!toggle) return;

        e.preventDefault();

        const theme = html.classList.contains("dark-mode")
            ? "light"
            : "dark";

        applyTheme(theme);

    });

})();

  function closePromoTicker() {



    var ticker = document.getElementById("promoTicker");



    if (ticker) {



      ticker.style.display = "none";



      var searchOverlay = document.getElementById("fullscreenSearch");



      if (searchOverlay && searchOverlay.classList.contains("show")) {



        var dimensions = getCalculatedHeight();



        searchOverlay.style.top = dimensions.top;



        searchOverlay.style.height = dimensions.height;



      }



    }



  }



  var isTransitioning = false;



  var recognition;



  var isListening = false;



  var originalTitle = "HOW CAN WE HELP YOU TODAY?";







  var SEARCH_MIN_LENGTH = 3;



  var SEARCH_JSON_URL = "/assets/js/search-site.json";



  var searchIndex = null;



  var searchIndexPromise = null;



  var searchDebounceTimer = null;







  function escapeHtml(str) {



    return String(str || "")



      .replace(/&/g, "&")



      .replace(//g, ">")



      .replace(/"/g, """);



  }







  function loadSearchIndex() {



    if (searchIndex) {



      return Promise.resolve(searchIndex);



    }







    if (searchIndexPromise) {



      return searchIndexPromise;



    }







    searchIndexPromise = fetch(SEARCH_JSON_URL)



      .then(function (response) {



        if (!response.ok) {



          throw new Error("Failed to load search data");



        }



        return response.json();



      })



      .then(function (data) {



        searchIndex = Array.isArray(data) ? data : [];



        return searchIndex;



      })



      .catch(function (error) {



        console.error("Search index error:", error);



        searchIndex = [];



        searchIndexPromise = null;



        return searchIndex;



      });







    return searchIndexPromise;



  }







  function filterSearchResults(query, data) {



    var normalizedQuery = query.toLowerCase();







    return data.filter(function (item) {



      var title = (item.title || "").toLowerCase();



      var name = (item.name || "").toLowerCase();



      return (



        title.indexOf(normalizedQuery) !== -1 ||



        name.indexOf(normalizedQuery) !== -1



      );



    });



  }







  function renderSuggestions(items, showEmptyState) {



    var box = document.getElementById("suggestionsBox");



    var wrapper = document.getElementById("searchBarWrapper");







    if (!box || !wrapper) {return;}







    if (!items.length) {



      if (showEmptyState) {showNoResults();} else {closeSuggestions();}



      return;



    }







    var html = "";



    items.forEach(function (item) {



      var title = escapeHtml(item.title || "");



      var url = escapeHtml(item.url || "#");



      var target = item.target === "_blank" ? "_blank" : "_self";



      var targetAttr =



        target === "_blank"



          ? ' target="_blank" rel="noopener noreferrer"'



          : "";







      html +=



        '' +



        '' +



        "" +



        title +



        "" +



        "";



    });







    box.innerHTML = html;



    box.scrollTop = 0;







    if (items.length > 5) {



      box.style.height = "240px";



    } else {



      box.style.height = items.length * 56 + "px";



    }







    wrapper.classList.add("has-suggestions");



    box.classList.add("animated-open");



  }







  function showNoResults() {



    var box = document.getElementById("suggestionsBox");



    var wrapper = document.getElementById("searchBarWrapper");







    if (!box || !wrapper) {return;}







    box.innerHTML =



      '
' +



      '' +



      "No record found" +



      "";



    box.style.height = "56px";



    wrapper.classList.add("has-suggestions");



    box.classList.add("animated-open");



  }







  function showSearchLoading() {



    var box = document.getElementById("suggestionsBox");



    var wrapper = document.getElementById("searchBarWrapper");







    if (!box || !wrapper) {return;}







    box.innerHTML =



      '
' +



      '' +



      "Searching..." +



      "";



    box.style.height = "56px";



    wrapper.classList.add("has-suggestions");



    box.classList.add("animated-open");



  }







  if ("webkitSpeechRecognition" in window || "SpeechRecognition" in window) {



    var SpeechRecognition =



      window.SpeechRecognition || window.webkitSpeechRecognition;



    recognition = new SpeechRecognition();



    recognition.continuous = false;



    recognition.interimResults = false;



    recognition.lang = "en-US";







    recognition.onstart = function () {



      if (isTransitioning) return;



      isListening = true;



      closeSuggestions();



      var voicePanel = document.getElementById("inlineVoicePanel");



      var titleEl = document.getElementById("searchMainTitle");



      var inputEl = document.getElementById("mainSearchInput");



      var clearBtn = document.getElementById("clearSearchInputBtn");







      if (voicePanel) voicePanel.classList.add("active");



      if (titleEl) titleEl.innerText = "LISTENING...";



      if (clearBtn) clearBtn.style.display = "none"; // Hide clear button when listening



      if (inputEl) {



        inputEl.disabled = true;



        inputEl.placeholder = "Listening to your voice...";



      }



    };







    recognition.onerror = function (event) {



      if (event && event.error) {



        console.warn("Voice search error:", event.error);



      }



      var inputEl = document.getElementById("mainSearchInput");



      if (inputEl) {



        if (event && event.error === "not-allowed") {



          inputEl.placeholder = "Microphone access denied — allow mic in browser settings";



        } else if (event && event.error === "network") {



          inputEl.placeholder = "Voice search unavailable — please use Google Chrome";



        }



      }



      resetVoiceUI();



    };



    recognition.onend = function () {resetVoiceUI();};







    recognition.onresult = function (event) {



      if (isTransitioning) return;



      var transcript = event.results[0][0].transcript;



      var searchInput = document.getElementById("mainSearchInput");



      if (searchInput) {



        searchInput.value = transcript;



        handleSearchInput(transcript);



      }



      resetVoiceUI();



    };



  }







  function toggleVoiceSearch() {



    if (!recognition || isTransitioning) return;



    if (!isListening) {



      try {recognition.start();} catch (e) {



        console.log("Speech block loop.");



      }



    } else {recognition.stop();}



  }







  function resetVoiceUI() {



    isListening = false;



    var voicePanel = document.getElementById("inlineVoicePanel");



    var titleEl = document.getElementById("searchMainTitle");



    var inputEl = document.getElementById("mainSearchInput");







    if (voicePanel) voicePanel.classList.remove("active");



    if (titleEl) titleEl.innerHTML = originalTitle;







    if (inputEl) {



      inputEl.disabled = false;



      inputEl.placeholder = "SEARCH";







      // Update clear button visibility based on layout recovery state



      toggleClearButtonVisibility(inputEl.value);







      var searchOverlay = document.getElementById("fullscreenSearch");



      if (



        searchOverlay &&



        searchOverlay.classList.contains("show") &&



        !isTransitioning



      ) {inputEl.focus();}



    }



  }







  function toggleClearButtonVisibility(val) {



    var clearBtn = document.getElementById("clearSearchInputBtn");



    if (clearBtn) {



      if (val.trim().length > 0 && !isListening) {



        clearBtn.style.display = "block";



      } else {



        clearBtn.style.display = "none";



      }



    }



  }







  function clearSearchField() {



    if (isTransitioning) return;







    var inputEl = document.getElementById("mainSearchInput");



    if (inputEl) {



      inputEl.value = "";



      toggleClearButtonVisibility("");



      closeSuggestions();



      inputEl.focus();



    }



  }







  function handleSearchInput(val) {



    if (isTransitioning) return;







    toggleClearButtonVisibility(val);







    var query = val.trim();







    if (searchDebounceTimer) {clearTimeout(searchDebounceTimer);}







    if (!query || query.length < SEARCH_MIN_LENGTH) {



      closeSuggestions();



      return;



    }







    if (!searchIndex) {showSearchLoading();}







    searchDebounceTimer = setTimeout(function () {



      var inputEl = document.getElementById("mainSearchInput");



      var currentQuery = inputEl ? inputEl.value.trim() : "";







      if (!currentQuery || currentQuery.length < SEARCH_MIN_LENGTH) {



        closeSuggestions();



        return;



      }







      loadSearchIndex().then(function (data) {



        var latestQuery = inputEl ? inputEl.value.trim() : "";







        if (latestQuery !== currentQuery) {return;}







        renderSuggestions(filterSearchResults(latestQuery, data), true);



      });



    }, 250);



  }







  function closeSuggestions() {



    var box = document.getElementById("suggestionsBox");



    var wrapper = document.getElementById("searchBarWrapper");







    if (box && wrapper) {



      box.classList.remove("animated-open");



      wrapper.classList.remove("has-suggestions");



      box.style.height = "0px";



    }



  }







  function getCalculatedHeight() {



    var mainHeader = document.getElementById("mainHeader");



    if (mainHeader) {



      var headerHeight = mainHeader.offsetHeight;



      return {



        top: headerHeight - 5 + "px",



        height: "calc(100vh - " + (headerHeight - 5) + "px)",



      };



    }



    return { top: "80px", height: "100vh" };



  }







  function openMobileNav() {



    closeSearch(true);



    if (typeof openNav === "function") {openNav();}



  }







  function toggleSearch() {



    if (isTransitioning) return;







    var searchOverlay = document.getElementById("fullscreenSearch");



    var mainHeader = document.getElementById("mainHeader");



    var inputEl = document.getElementById("mainSearchInput");







    if (!searchOverlay.classList.contains("show")) {



      isTransitioning = true;



      if (typeof closeNav === "function") {closeNav();}



      if (inputEl) inputEl.value = "";



      toggleClearButtonVisibility("");



      closeSuggestions();







      var dimensions = getCalculatedHeight();



      searchOverlay.style.top = dimensions.top;



      searchOverlay.style.height = dimensions.height;







      mainHeader.classList.add("no-shadow-border");



      searchOverlay.classList.add("show");



      document.body.style.overflow = "hidden";







      setTimeout(function () {



        isTransitioning = false;



        if (inputEl) inputEl.focus();



      }, 800);



    }



  }







  function closeSearch(force) {



    if (isTransitioning && !force) return;







    var searchOverlay = document.getElementById("fullscreenSearch");



    var mainHeader = document.getElementById("mainHeader");







    if (searchOverlay.classList.contains("show")) {



      isTransitioning = true;







      if (recognition && isListening) {recognition.stop();}



      resetVoiceUI();



      closeSuggestions();







      if (document.getElementById("mainSearchInput")) {



        document.getElementById("mainSearchInput").value = "";



        toggleClearButtonVisibility("");



      }







      searchOverlay.style.height = "0";



      searchOverlay.classList.remove("show");



      document.body.style.overflow = "";







      setTimeout(function () {



        mainHeader.classList.remove("no-shadow-border");



        isTransitioning = false;



      }, 800);



    }



  }







  document.addEventListener("click", function (event) {



    var wrapper = document.getElementById("searchBarWrapper");



    if (wrapper && !wrapper.contains(event.target)) {closeSuggestions();}



  });







  window.addEventListener("resize", function () {



    var searchOverlay = document.getElementById("fullscreenSearch");



    if (searchOverlay && searchOverlay.classList.contains("show")) {



      var dimensions = getCalculatedHeight();



      searchOverlay.style.top = dimensions.top;



      searchOverlay.style.height = dimensions.height;



    }



  });



  document.addEventListener("click", function (event) {



    var targetLink = event.target.closest(".mobile-nav ul li:first-child a");







    if (targetLink) {



      event.preventDefault();







      toggleSearch();



    }



  });







  function switchMobileMenu(type) {



    var isPersonal = type === "personal";



    var nav = document.getElementById("myNav");







    document.querySelectorAll(".mob-menu-section").forEach(function (section) {



      var sectionType = section.getAttribute("data-menu-type");



      section.style.display = sectionType === type ? "" : "none";



    });







    var personalTab = document.querySelector("#myNav .personal-drop");



    var businessTab = document.querySelector("#myNav .business-drop");







    if (personalTab) {



      personalTab.classList.toggle("active-main-menu", isPersonal);



    }



    if (businessTab) {



      businessTab.classList.toggle("active-main-menu", !isPersonal);



    }







    if (nav && typeof closeSubMenu === "function") {closeSubMenu();} else if (nav) {



      nav.classList.remove("submenu-open");



      var level1 = nav.querySelector(".menu-level.level-1");



      var level2 = nav.querySelector(".menu-level.level-2");



      if (level1) level1.style.display = "";



      if (level2) level2.style.display = "none";



      nav.querySelectorAll(".submenu").forEach(function (sub) {



        sub.style.display = "none";



      });



    }



  }

document.addEventListener('DOMContentLoaded', () => {







  function initTabs(section) {



    const tabs = section.querySelectorAll('.tabs-content .tabs');



    const tabButtons = section.querySelectorAll('.menu-box [data-tab]');







    function activateTab(tabName) {







      tabs.forEach(tab => {



        if (tab.getAttribute('data-tab') === tabName) {tab.classList.add('active');} else {tab.classList.remove('active');}



      });







      tabButtons.forEach(btn => {



        btn.classList.toggle(



          'active',



          btn.getAttribute('data-tab') === tabName



        );



      });



    }







    // Default first tab active



    if (tabButtons.length > 0) {activateTab(tabButtons[0].getAttribute('data-tab'));}







    tabButtons.forEach(btn => {



      btn.addEventListener('click', (e) => {



        e.preventDefault();



        const tabName = btn.getAttribute('data-tab');



        activateTab(tabName);



      });



    });



  }







  document.querySelectorAll('.tab-section').forEach(section => {initTabs(section);});







});

