const accordions = document.querySelectorAll(".accordion");







accordions.forEach(accordion => {



  const header = accordion.querySelector(".accordion-header");



  const content = accordion.querySelector(".accordion-content");







  header.addEventListener("click", () => {



    // Close all others



    accordions.forEach(item => {



      if (item !== accordion) {



        item.classList.remove("active");



        item.querySelector(".accordion-content").style.maxHeight = null;



      }



    });







    // Toggle current



    if (accordion.classList.contains("active")) {



      accordion.classList.remove("active");



      content.style.maxHeight = null;



    } else {



      accordion.classList.add("active");



      content.style.maxHeight = content.scrollHeight + "px";



    }



  });



});

function openNav() {



  document.getElementById("myNav").style.width = "100%";



}



function closeNav() {



  document.getElementById("myNav").style.width = "0";



  document.querySelector(".level-2").classList.remove("active");



}



function closeSubMenu() {document.querySelector(".level-2").classList.remove("active");}



// Dynamic submenu open



document.querySelectorAll(".arrow").forEach(function (el) {



  el.addEventListener("click", function (e) {



    e.preventDefault();



    e.stopPropagation();







    let menuId = this.getAttribute("data-menu");







    document.querySelector(".level-2").classList.add("active");







    document.querySelectorAll(".submenu").forEach(function (menu) {



      menu.style.display = "none";



    });







    document.getElementById(menuId).style.display = "block";



  });



});

document.querySelectorAll('.js-hover').forEach(wrapper => {



  // Select all list items in the left-nav list



  const listItems = wrapper.querySelectorAll('.lft-lv1-nav ul li');



  let activeDiv = null;



  listItems.forEach(item => {



    item.addEventListener('mouseenter', () => {



      // pehle sab hover divs hide



      wrapper.querySelectorAll('[class*="hover-div"]').forEach(div => {div.classList.remove('active');});



      // trigger ka class find karo (trigger ya trigger-2 etc)



      let triggerClass = [...item.classList].find(c => c.startsWith('trigger'));



      if (!triggerClass) {



        activeDiv = null;



        return;



      }



      // suffix nikaalo



      let suffix = triggerClass.split('-')[1] || '';



      // matching hover-div class banao



      let targetClass = suffix ? `hover-div-${suffix}` : 'hover-div';



      let targetDiv = wrapper.querySelector(`.${targetClass}`);



      if (targetDiv) {



        targetDiv.classList.add('active');



        activeDiv = targetDiv;



      }



    });



  });







  wrapper.addEventListener('mouseleave', () => {



    if (activeDiv) {



      activeDiv.classList.remove('active');



      activeDiv = null;



    }



  });







});

const tabs = document.querySelectorAll('.tabs li');



const panes = document.querySelectorAll('.tab-pane');







tabs.forEach(tab => {



  tab.addEventListener('click', () => {







    // remove active from all tabs



    tabs.forEach(t => t.classList.remove('active'));



    panes.forEach(p => p.classList.remove('active'));







    // add active to clicked tab



    tab.classList.add('active');



    document.getElementById(tab.dataset.tab).classList.add('active');







  });



});
